const failStaleHomeCheckpoints = `-- name: FailStaleHomeCheckpoints :many
UPDATE home_checkpoints
SET status = 'failed', finished_at = now(),
    error = $1
WHERE org_id = $2 AND status = 'requested' AND attempts = 0
  AND requested_at < now() - make_interval(secs => $3::int)
RETURNING org_id, id, agent_id, reason, status, sandbox_id, generation, epoch, snapshot_id, size_bytes, attempts, error, requested_at, started_at, finished_at, repository_epoch, snapshot_missing_at
`

type FailStaleHomeCheckpointsParams struct {
	Error       pgtype.Text
	OrgID       pgtype.UUID
	WaitSeconds int32
}

// Requests that never started because the sandbox was not ready for the configured wait.
func (q *Queries) FailStaleHomeCheckpoints(ctx context.Context, arg FailStaleHomeCheckpointsParams) ([]HomeCheckpoint, error) {
	rows, err := q.db.Query(ctx, failStaleHomeCheckpoints, arg.Error, arg.OrgID, arg.WaitSeconds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []HomeCheckpoint
	for rows.Next() {
		var i HomeCheckpoint
		if err := rows.Scan(
			&i.OrgID,
			&i.ID,
			&i.AgentID,
			&i.Reason,
			&i.Status,
			&i.SandboxID,
			&i.Generation,
			&i.Epoch,
			&i.SnapshotID,
			&i.SizeBytes,
			&i.Attempts,
			&i.Error,
			&i.RequestedAt,
			&i.StartedAt,
			&i.FinishedAt,
			&i.RepositoryEpoch,
			&i.SnapshotMissingAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

