const requestHourlyHomeCheckpoints = `-- name: RequestHourlyHomeCheckpoints :many
INSERT INTO home_checkpoints (org_id, agent_id, reason, sandbox_id, generation)
SELECT s.org_id, s.agent_id, 'hourly', coalesce(s.sandbox_id, ''), coalesce(s.home_generation, '')
FROM agent_sandboxes s
JOIN agents a ON a.org_id = s.org_id AND a.id = s.agent_id
LEFT JOIN agent_versions v ON v.org_id = a.org_id AND v.id = a.active_version_id
WHERE s.org_id = $1 AND s.state = 'ready' AND s.unhealthy_at IS NULL
  AND s.restore_checkpoint_id IS NULL AND a.status = 'active'
  AND (v.config->>'ephemeral')::boolean IS NOT TRUE
  AND NOT EXISTS (
      SELECT 1 FROM home_checkpoints c
      WHERE c.org_id = s.org_id AND c.agent_id = s.agent_id
        AND (c.status IN ('requested', 'running')
             OR c.requested_at > now() - make_interval(secs => $2::int)))
ON CONFLICT (org_id, agent_id) WHERE status IN ('requested', 'running') DO NOTHING
RETURNING org_id, id, agent_id, reason, status, sandbox_id, generation, epoch, snapshot_id, size_bytes, attempts, error, requested_at, started_at, finished_at, repository_epoch, snapshot_missing_at
`

type RequestHourlyHomeCheckpointsParams struct {
	OrgID           pgtype.UUID
	IntervalSeconds int32
}

// Ephemeral agents have no home that outlives a run and are not checkpointed (ADR 0065 13c).
// One request per agent whose sandbox is ready, has no restore pending (an empty home must not
// become the newest checkpoint) and has had no checkpoint requested for @interval_seconds.
func (q *Queries) RequestHourlyHomeCheckpoints(ctx context.Context, arg RequestHourlyHomeCheckpointsParams) ([]HomeCheckpoint, error) {
	rows, err := q.db.Query(ctx, requestHourlyHomeCheckpoints, arg.OrgID, arg.IntervalSeconds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []HomeCheckpoint
	for rows.Next() {
		var i HomeCheckpoint
		if err := rows.Scan(
			&i.OrgID,
			&i.ID,
			&i.AgentID,
			&i.Reason,
			&i.Status,
			&i.SandboxID,
			&i.Generation,
			&i.Epoch,
			&i.SnapshotID,
			&i.SizeBytes,
			&i.Attempts,
			&i.Error,
			&i.RequestedAt,
			&i.StartedAt,
			&i.FinishedAt,
			&i.RepositoryEpoch,
			&i.SnapshotMissingAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

